package com.aistock.market.statistics;
import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.common.statistics.*;import java.time.*;import java.sql.Timestamp;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.util.LinkedMultiValueMap;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class MarketStatisticsMysqlTest {
 static final Instant NOW=Instant.parse("2026-10-22T04:00:00Z");
 static StatisticsWindow window(){return StatisticsWindow.parse(new LinkedMultiValueMap<>(),Clock.fixed(NOW,ZoneOffset.UTC));}
 static String version(JdbcTemplate j,String instrument,String provider,String hash,String end){var id=UUID.randomUUID().toString();j.update("insert into market_data_version(version_id,instrument_id,provider,price_basis,status,quality,content_hash,source_payload_hash,fetched_at,published_at,coverage_start,coverage_end) values(?,?,?,'RAW','AVAILABLE','VERIFIED',?,?,?,?,'2026-01-01',?)",id,instrument,provider,hash.repeat(64),"f".repeat(64),Timestamp.from(NOW),Timestamp.from(NOW),end);return id;}
 @Test void countsOnlyCurrentHeadsAndIncludesUninitializedStocksInPagination(){var j=new MarketDatabaseFixture().jdbc();for(var id:List.of("SH600030","SH600276","SZ000002"))j.update("insert into instrument(instrument_id,ticker,display_name,demo_only) values(?,?,?,false)",id,id,"test");var a=version(j,"SH600030","BAOSTOCK","a","2026-10-20");var b=version(j,"SH600030","TUSHARE","b","2026-10-21");version(j,"SH600030","BAOSTOCK","c","2026-10-19");
  for(var entry:Map.of("BAOSTOCK",a,"TUSHARE",b).entrySet())j.update("insert into instrument_data_head(instrument_id,provider,price_basis,version_id,checked_at) values('SH600030',?,'RAW',?,?)",entry.getKey(),entry.getValue(),Timestamp.from(NOW));
  j.update("insert into instrument_data_head(instrument_id,provider,price_basis,version_id,checked_at,last_error_code) values('SZ000002','BAOSTOCK','RAW',null,?,'SOURCE_UNAVAILABLE')",Timestamp.from(NOW));var before=j.queryForList("select * from instrument_data_head order by instrument_id,provider");var repo=new MarketStatisticsRepository(j);var first=repo.summary(window(),1,2,NOW);assertEquals("1",first.instrumentCount());assertEquals("2",first.availableHeads());assertEquals(2,first.items().size());assertTrue(first.hasMore());assertEquals(Set.of(LocalDate.parse("2026-10-20"),LocalDate.parse("2026-10-21")),first.items().stream().map(x->x.coverageEnd()).collect(java.util.stream.Collectors.toSet()));
  var second=repo.summary(window(),2,2,NOW);assertFalse(second.hasMore());assertEquals("SH600276",second.items().get(0).instrumentId());assertNull(second.items().get(0).provider());assertNull(second.items().get(0).versionId());assertEquals("SZ000002",second.items().get(1).instrumentId());assertNull(second.items().get(1).coverageEnd());assertEquals(before,j.queryForList("select * from instrument_data_head order by instrument_id,provider"));j.update("update market_data_version set status='UNAVAILABLE' where version_id=?",a);assertEquals("1",repo.summary(window(),1,20,NOW).availableHeads());
 }
 @Test void demoOnlyHasNoAvailableHeadAndInvalidPagesFail(){var r=new MarketStatisticsRepository(new MarketDatabaseFixture().jdbc());var v=r.summary(window(),1,20,NOW);assertEquals("0",v.instrumentCount());assertTrue(v.items().isEmpty());assertThrows(com.aistock.common.BusinessException.class,()->r.summary(window(),0,20,NOW));}
}
